{"cards": [{"node_code": "N_e6cc4b13d58637d7", "definition": "研究水下航行器（AUV/ROV）及水面无人艇（USV）的设计、推进、导航与作业技术，涵盖深海探测、水下通信及水面自主航行。", "boundary": "聚焦于水体环境（水下及水面）的机器人本体与系统。边界在于强调流体环境适应性，如耐压、浮力控制、水声通信及波浪补偿。陆地移动、空中飞行或通用机械臂技术不作为主挂载，除非作为水下/水面平台的附属执行机构。", "includes": ["自主水下航行器（AUV）与遥控水下机器人（ROV）的机构与控制系统", "水面无人艇（USV）的船体设计、动力推进及自主航行技术", "水下声学通信、定位导航及深海作业工具"], "excludes": ["陆地轮式/履带机器人或空中无人机", "纯海洋水文物理研究或纯水声信号处理理论（除非直接服务于机器人平台）"], "sibling_distinctions": [{"other_code": "N_b594d5a5d3096efb", "rule": "本节点专注于水体环境（水下/水面），兄弟节点专注于陆地农业、工程及救援场景。"}, {"other_code": "N_1a24d61efaafaad5", "rule": "本节点针对水体物理环境，兄弟节点针对核辐射、太空真空或高危工业环境。"}], "cross_boundary_rule": "若平台主要在水体中运行，主挂载本节点；若为水陆两栖且强调陆地越野能力，需根据主要任务场景判定，通常水下作业特性优先归入本节点。"}, {"node_code": "N_b594d5a5d3096efb", "definition": "研究应用于农业生产、土木工程及灾害救援领域的特种移动机器人，涵盖其地形适应性、作业执行及人机协作技术。", "boundary": "聚焦于陆地非结构化或半结构化环境中的特定任务应用。边界在于强调“任务专用性”与“环境交互”，如农田耕作、建筑砌筑、废墟搜救。通用底盘技术归入上级节点，纯感知算法归入智能控制节点。", "includes": ["农业机器人（播种、采摘、除草）及畜牧管理机器人", "工程建筑机器人（砌筑、焊接、检测）及基础设施巡检机器人", "灾害救援机器人（废墟搜索、排爆、伤员转运）"], "excludes": ["水下或空中机器人", "通用工业机械臂（固定基座）或纯物流仓储AGV（若未强调特种环境适应性）"], "sibling_distinctions": [{"other_code": "N_e6cc4b13d58637d7", "rule": "本节点专注于陆地农业/工程/救援场景，兄弟节点专注于水体环境。"}, {"other_code": "N_1a24d61efaafaad5", "rule": "本节点针对常规陆地特种任务，兄弟节点针对核、空间等极端危险环境。"}], "cross_boundary_rule": "若机器人用于农田但具备水下作业能力（如稻田插秧），主挂载本节点；若用于核电站内部，主挂载“核、空间与危险环境机器人”。"}, {"node_code": "N_1a24d61efaafaad5", "definition": "研究适用于核设施、太空、高危工业及极端物理环境（高温、高压、辐射、真空）的特种机器人，强调防护、远程操控及自主生存能力。", "boundary": "聚焦于人类无法直接生存或进入的极端环境。边界在于强调“环境极端性”与“安全隔离”，如防辐射屏蔽、真空密封、抗高温材料。常规陆地农业或普通救援机器人不归入此类，除非涉及核泄漏等特定危险源。", "includes": ["核电站维护、乏燃料处理及核事故处置机器人", "太空探测、卫星在轨服务及月球/火星漫游机器人", "高危工业（化工、矿山）及极端温度/压力环境下的作业机器人"], "excludes": ["常规陆地农业、建筑或普通城市救援机器人", "水下机器人（除非涉及深海高压极端环境且与核/空间无关，通常归入水下节点）"], "sibling_distinctions": [{"other_code": "N_b594d5a5d3096efb", "rule": "本节点针对核、太空等极端危险环境，兄弟节点针对常规陆地农业、工程及救援场景。"}, {"other_code": "N_e6cc4b13d58637d7", "rule": "本节点针对核/太空/高危工业环境，兄弟节点针对水体环境。"}], "cross_boundary_rule": "若机器人用于核电站水下反应堆检查，主挂载本节点（因核环境主导）；若用于深海油气平台水下作业，主挂载“水下机器人与水面无人平台”。"}]}
